class Counter {
  static total = 0;

  constructor() {
    Counter.total += 1;
  }

  static isSelf() {
    return this === Counter;
  }
}

const a = new Counter();
const b = new Counter();
console.log(Counter.total);
console.log(a.total);
console.log(Counter.isSelf());
console.log(typeof b.isSelf);
